INSERT INTO `techfix_accessory` VALUES (1,'Anker 65W USB-C Charger','Anker','Fast GaN charger for laptops, phones and tablets.',1995.00,'Compatible with USB-C laptops, Galaxy A55, and most phones.',25,'accessories/1.jpg','2026-10-14 15:07:38.546000',3,''),(2,'Logitech K380 Keyboard','Logitech','Compact Bluetooth keyboard for multi-device typing.',1795.00,'Works with Windows, macOS, Android, iOS via Bluetooth.',20,'accessories/2.jpg','2026-10-14 15:07:38.558000',2,''),(3,'Anker 65W GaN Charger','Anker','Compact 3-port fast charger for laptop and phone.',2495.00,'USB-C PD, compatible with laptops/phones/tablets',25,'accessories/3.jpg','2026-10-15 05:17:32.582000',3,''),(4,'Logitech G304 Mouse','Logitech','Wireless gaming mouse with long battery life.',2195.00,'2.4GHz wireless + USB receiver',22,'accessories/4.jpg','2026-10-15 05:17:32.598000',9,''),(5,'Sony WH-CH520 Headphones','Sony','Lightweight on-ear Bluetooth headphones, 50h battery.',3490.00,'Bluetooth 5.2, 3.5mm backup cable',14,'accessories/5.jpg','2026-10-15 05:17:32.605000',2,''),(6,'JBL Tune Buds','JBL','True wireless earbuds with noise cancelling.',3995.00,'Bluetooth, USB-C charging case',16,'accessories/6.jpg','2026-10-15 05:17:32.609000',2,''),(7,'UGREEN USB-C Hub 6-in-1','UGREEN','HDMI + USB + SD hub for USB-C laptops.',1895.00,'Compatible with USB-C laptops/tablets',20,'accessories/7.jpg','2026-10-15 05:17:32.615000',3,''),(8,'Baseus 10000mAh Powerbank','Baseus','22.5W fast-charging powerbank with display.',1495.00,'USB-C + USB-A, for phones/tablets',30,'accessories/8.jpg','2026-10-15 05:17:32.617000',3,''),(10,'Apple 20W USB-C Power Adapter','Apple','Fast-charge any iPhone from 0 to 50% in around 30 minutes.',1290.00,'Works with all iPhone models (USB-C cable required).',40,'accessories/10.jpg','2026-10-15 06:39:09.764000',3,''),(11,'Apple USB-C to Lightning Cable (1m)','Apple','Charge and sync Lightning iPhones with USB-C power adapters.',1190.00,'For Lightning iPhones: 11, 12 series, 13 series, SE 3